5: public class Gate {
6:     public static String read(String baseRoot, String payload) throws IOException {
7:         Path root = Path.of(baseRoot).toAbsolutePath().normalize();
8:         Path candidate = root.resolve(payload).normalize();
9:         if (!candidate.startsWith(root)) {
10:             return "blocked";
11:         }
12:         return Files.readString(candidate);
13:     }
14: }
